public class FakeMvc {
  private final HealthController controller;
  public FakeMvc(HealthController c) { this.controller = c; }
  public Response perform(String method, String path) { return controller.handle(method, path); }
  public static class Response {
    public final int status; public final String body;
    private Response(int s, String b) { status = s; body = b; }
    public static Response of(int s, String b) { return new Response(s, b); }
    public String jsonPath(String key) {
      String needle = "\"" + key + "\":\"";
      int i = body.indexOf(needle);
      if (i < 0) return null;
      int start = i + needle.length();
      int end = body.indexOf('"', start);
      return end < 0 ? null : body.substring(start, end);
    }
  }
}

