import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class HealthMvcTest {
    @Test
    void healthIsUp() {
        FakeMvc mvc = new FakeMvc(new HealthController());
        FakeMvc.Response res = mvc.perform("GET", "/health");
        assertEquals(200, res.status);
        assertEquals("UP", res.jsonPath("status"));
    }
}
